import{_ as i,a0 as l,w as o,s as d,I as n,x as a,a1 as e,A as p,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"使用 Python 處理 JSON 格式的數據 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 處理 JSON 格式的數據 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 處理 JSON 格式的數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 處理 JSON 格式的數據 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190716 Save and load Python data with JSON","title":"使用 Python 處理 JSON 格式的數據","tag":"201907","desc":""},"relativePath":"201907/20190716 Save and load Python data with JSON.md","filePath":"[post].md"}'),r={name:"201907/20190716 Save and load Python data with JSON.md"};function u(c,s,b,g,k,m){const t=l("Link");return o(),d("div",null,[s[19]||(s[19]=n("h1",{id:"使用-python-處理-json-格式的數據",tabindex:"-1"},[a("使用 Python 處理 JSON 格式的數據 "),n("a",{class:"header-anchor",href:"#使用-python-處理-json-格式的數據","aria-label":"Permalink to “使用 Python 處理 JSON 格式的數據”"},"​")],-1)),s[20]||(s[20]=n("blockquote",null,[n("p",null,"如果你不希望從頭開始創造一種數據格式來存放數據，JSON 是一個很好的選擇。如果你對 Python 有所瞭解，就更加事半功倍了。下面就來介紹一下如何使用 Python 處理 JSON 數據。")],-1)),s[21]||(s[21]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bus_cloud_database.png?itok=lhhU42fg",alt:"Cloud and databsae incons",title:"Cloud and databsae incons"})],-1)),n("p",null,[e(t,{href:"https://json.org"},{default:p(()=>[...s[0]||(s[0]=[a("JSON",-1)])]),_:1}),s[1]||(s[1]=a(" 的全稱是 ",-1)),s[2]||(s[2]=n("ruby",null,[a("JavaScript 對象表示法"),n("rt",null,"JavaScript Object Notation")],-1)),s[3]||(s[3]=a("。這是一種以鍵值對的形式存儲數據的格式，並且很容易解析，因而成為了一種被廣泛使用的數據格式。另外，不要因為 JSON 名稱而望文生義，JSON 並不僅僅在 JavaScript 中使用，它也可以在其它語言中使用。下文會介紹它是如何在 Python 中使用的。",-1))]),s[22]||(s[22]=h(`<p>首先我們給出一個 JSON 示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;:&quot;tux&quot;,</span></span>
<span class="line"><span>    &quot;health&quot;:&quot;23&quot;,</span></span>
<span class="line"><span>    &quot;level&quot;:&quot;4&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面是一個和編程語言無關的原生 JSON 數據。熟悉 Python 的人會看出來這個 JSON 數據跟 Python 中的<ruby>字典<rt>dictionary</rt></ruby>長得很像。而這兩者之間確實非常相似，如果你對 Python 中的列表和字典數據結構有一定的理解，那麼 JSON 理解起來也不難。</p><h3 id="使用字典存放數據" tabindex="-1">使用字典存放數據 <a class="header-anchor" href="#使用字典存放數據" aria-label="Permalink to “使用字典存放數據”">​</a></h3><p>如果你的應用需要存儲一些結構複雜的數據，不妨考慮使用 JSON 格式。對比你可能曾經用過的自定義格式的文本配置文件，JSON 提供了更加結構化的可遞歸的存儲格式。同時，Python 自帶的 <code>json</code> 模組已經提供了可以將 JSON 數據導入/導出應用時所需的所有解析庫。因此，你不需要針對 JSON 自行編寫代碼進行解析，而其他開發人員在與你的應用進行數據交互的時候也不需要去解析新的數據格式。正是這個原因，JSON 在數據交換時被廣泛地採用了。</p><p>以下是一段在 Python 中使用嵌套字典的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env python3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import json</span></span>
<span class="line"><span></span></span>
<span class="line"><span># instantiate an empty dict</span></span>
<span class="line"><span>team = {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># add a team member</span></span>
<span class="line"><span>team[&#39;tux&#39;] = {&#39;health&#39;: 23, &#39;level&#39;: 4}</span></span>
<span class="line"><span>team[&#39;beastie&#39;] = {&#39;health&#39;: 13, &#39;level&#39;: 6}</span></span>
<span class="line"><span>team[&#39;konqi&#39;] = {&#39;health&#39;: 18, &#39;level&#39;: 7}</span></span></code></pre></div><p>這段代碼聲明瞭一個名為 <code>team</code> 的字典，並初始化為一個空字典。</p><p>如果要給這個字典添加內容，首先需要創建一個鍵，例如上面示例中的 <code>tux</code>、<code>beastie</code>、<code>konqi</code>，然後為這些鍵一一提供對應的值。上面示例中的值由一個個包含遊戲玩家信息的字典充當。</p><p>字典是一種可變的變量。字典中的數據可以隨時添加、刪除或更新。這樣的特性使得字典成為了應用程序存儲數據的極好選擇。</p><h3 id="使用-json-格式存儲數據" tabindex="-1">使用 JSON 格式存儲數據 <a class="header-anchor" href="#使用-json-格式存儲數據" aria-label="Permalink to “使用 JSON 格式存儲數據”">​</a></h3><p>如果存放在字典中的數據需要持久存儲，這些數據就需要寫到文件當中。這個時候就需要用到 Python 中的 <code>json</code> 模組了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(&#39;mydata.json&#39;, &#39;w&#39;) as f:</span></span>
<span class="line"><span>    json.dump(team, f)</span></span></code></pre></div><p>上面的代碼首先創建了一個名為 <code>mydata.json</code> 的文件，然後以寫模式打開了這個文件，這個被打開的文件以變量 <code>f</code> 表示（當然也可以用任何你喜歡的名稱，例如 <code>file</code>、<code>output</code> 等）。而 <code>json</code> 模組中的 <code>dump()</code> 方法則是用於將一個字典輸出到一個文件中。</p><p>從應用中導出數據就是這麼簡單，同時這些導出的數據是結構化的、可理解的。現在可以查看導出的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat mydata.json</span></span>
<span class="line"><span>{&quot;tux&quot;: {&quot;health&quot;: 23, &quot;level&quot;: 4}, &quot;beastie&quot;: {&quot;health&quot;: 13, &quot;level&quot;: 6}, &quot;konqi&quot;: {&quot;health&quot;: 18, &quot;level&quot;: 7}}</span></span></code></pre></div><h3 id="從-json-文件中讀取數據" tabindex="-1">從 JSON 文件中讀取數據 <a class="header-anchor" href="#從-json-文件中讀取數據" aria-label="Permalink to “從 JSON 文件中讀取數據”">​</a></h3><p>如果已經將數據以 JSON 格式導出到文件中了，也有可能需要將這些數據讀回到應用中去。這個時候，可以使用 Python <code>json</code> 模組中的 <code>load()</code> 方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env python3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>f = open(&#39;mydata.json&#39;)</span></span>
<span class="line"><span>team = json.load(f)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(team[&#39;tux&#39;])</span></span>
<span class="line"><span>print(team[&#39;tux&#39;][&#39;health&#39;])</span></span>
<span class="line"><span>print(team[&#39;tux&#39;][&#39;level&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(team[&#39;beastie&#39;])</span></span>
<span class="line"><span>print(team[&#39;beastie&#39;][&#39;health&#39;])</span></span>
<span class="line"><span>print(team[&#39;beastie&#39;][&#39;level&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span># when finished, close the file</span></span>
<span class="line"><span>f.close()</span></span></code></pre></div><p>這個方法實現了和保存文件大致相反的操作。使用一個變量 <code>f</code> 來表示打開了的文件，然後使用 <code>json</code> 模組中的 <code>load()</code> 方法讀取文件中的數據並存放到 <code>team</code> 變量中。</p><p>其中的 <code>print()</code> 展示瞭如何查看讀取到的數據。在過於複雜的字典中迭代調用字典鍵的時候有可能會稍微轉不過彎來，但只要熟悉整個數據的結構，就可以慢慢摸索出其中的邏輯。</p><p>當然，這裏使用 <code>print()</code> 的方式太不靈活了。你可以將其改寫成使用 <code>for</code> 循環的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in team.values():</span></span>
<span class="line"><span>    print(i)</span></span></code></pre></div><h3 id="使用-json" tabindex="-1">使用 JSON <a class="header-anchor" href="#使用-json" aria-label="Permalink to “使用 JSON”">​</a></h3><p>如上所述，在 Python 中可以很輕鬆地處理 JSON 數據。因此只要你的數據符合 JSON 的模式，就可以選擇使用 JSON。JSON 非常靈活易用，下次使用 Python 的時候不妨嘗試一下。</p><hr>`,26)),n("p",null,[s[5]||(s[5]=a("via: ",-1)),e(t,{href:"https://opensource.com/article/19/7/save-and-load-data-python-json"},{default:p(()=>[...s[4]||(s[4]=[a("https://opensource.com/article/19/7/save-and-load-data-python-json",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("作者：",-1)),e(t,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[6]||(s[6]=[a("Seth Kenlon",-1)])]),_:1}),s[11]||(s[11]=a(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),e(t,{href:"https://github.com/HankChow"},{default:p(()=>[...s[8]||(s[8]=[a("HankChow",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:p(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const N=i(r,[["render",u]]);export{S as __pageData,N as default};
